function vitest(name){
  const path=root+prefix+name+"-"+date+".log",text=read(path),line=text.match(/^\s*Tests\s+(.+)$/m)?.[1];
  assert(line,"Incomplete test log: "+path);
  const count=key=>Number(line.match(new RegExp("(\\d+) "+key))?.[1]??0);
  const logLines=text.split(/\r?\n/),failureHeaders=[];
  for(let i=0;i<logLines.length;i++)if(/^ FAIL\s+/.test(logLines[i])){
    const parts=[logLines[i].replace(/^ FAIL\s+/,"")];
    for(let j=i+1;j<logLines.length&&logLines[j].trim()&&!/^(?: FAIL\s+|(?:AssertionError|Error|TypeError):)/.test(logLines[j]);j++)parts.push(logLines[j]);
    failureHeaders.push(parts.join(" ").replace(/\s+/g," ").trim());
  }
  assert.equal(failureHeaders.length,count("failed"),"One exact failure header per failed test: "+path);
  assert.equal(new Set(failureHeaders).size,failureHeaders.length,"No duplicate failure headers");
  return {path,passed:count("passed"),failed:count("failed"),skipped:count("skipped"),total:Number(line.match(/\((\d+)\)/)?.[1]),
    files:text.match(/^\s*Test Files\s+(.+)$/m)?.[1].trim(),durationSeconds:Number(text.match(/Duration\s+([\d.]+)s/)?.[1]),failureHeaders};
}
